[GlobalClass]
public partial class EnemyAiAction : Resource
{
    public static readonly StringName TARGET_SELECTOR_NEAREST_ROLE_THREAT_ENEMY = "nearest_role_threat_enemy";
    protected const int HP_BASIS_POINTS_DENOMINATOR = 10000, ROLE_THREAT_MIN_EFFECTIVE_RANGE = 4, ROLE_THREAT_DISTANCE_WINDOW = 4, ROLE_THREAT_MAX_APPROACH_DISTANCE = 7, ROLE_THREAT_MAX_CONTACT_RANGE = 2;

    [Export] public StringName action_id { get; set; } = "";
    [Export] public StringName score_bucket_id { get; set; } = "";
    [Export] public StringName action_intent { get; set; } = "positioning";

    protected readonly BattleSkillResolutionRules _skill_resolution_rules = new BattleSkillResolutionRules();

    public virtual BattleAiDecision decide(GodotObject context) => null;
    public virtual Godot.Collections.Array<string> validate_schema() => _collect_base_validation_errors();

    public Godot.Collections.Array<StringName> get_declared_skill_ids() { var r = new Godot.Collections.Array<StringName>(); var s = new Godot.Collections.Dictionary(); _append_declared_skill_id(r, s, Get("skill_id")); var sv = Get("skill_ids"); if (sv.VariantType == Variant.Type.Array) foreach (var rsi in sv.AsGodotArray()) _append_declared_skill_id(r, s, rsi); var rsv = Get("range_skill_ids"); if (rsv.VariantType == Variant.Type.Array) foreach (var rsi in rsv.AsGodotArray()) _append_declared_skill_id(r, s, rsi); return r; }

    public Godot.Collections.Array<string> validate_skill_references(Godot.Collections.Dictionary skillDefs) { var e = new Godot.Collections.Array<string>(); foreach (var sid in get_declared_skill_ids()) { if (sid == "") e.Add($"AI action {action_id} references an empty skill_id."); else if (!skillDefs.ContainsKey(sid)) e.Add($"AI action {action_id} references missing skill {sid}."); } return e; }

    protected Godot.Collections.Array<string> _collect_base_validation_errors() { var e = new Godot.Collections.Array<string>(); if (action_id == "") e.Add("AI action is missing action_id."); var ts = Get("target_selector"); if (ts.VariantType == Variant.Type.String || ts.VariantType == Variant.Type.StringName) { var tsn = ProgressionDataUtils.to_string_name(ts); if (tsn != "" && !_is_supported_target_selector(tsn)) e.Add($"AI action {action_id} has unsupported target_selector {tsn}."); } return e; }

    protected static bool _is_supported_target_selector(StringName s) => s == "nearest_enemy" || s == "lowest_hp_enemy" || s == TARGET_SELECTOR_NEAREST_ROLE_THREAT_ENEMY || s == "nearest_ally" || s == "lowest_hp_ally" || s == "self";

    protected void _append_enemy_focus_target_selector_errors(Godot.Collections.Array<string> errors, string actionLabel, StringName selector) { if (selector == "nearest_ally" || selector == "lowest_hp_ally" || selector == "self") errors.Add($"{actionLabel} {action_id} has unsupported target_selector {selector}."); }

    protected static void _append_declared_skill_id(Godot.Collections.Array<StringName> results, Godot.Collections.Dictionary seen, Variant rawSkillId) { if (rawSkillId.VariantType != Variant.Type.String && rawSkillId.VariantType != Variant.Type.StringName) return; var sid = ProgressionDataUtils.to_string_name(rawSkillId); if (seen.ContainsKey(sid)) return; seen[sid] = true; results.Add(sid); }

