    protected Godot.Collections.Array<StringName> _resolve_known_skill_ids(GodotObject context, Godot.Collections.Array<StringName> preferredSkillIds = null) { var r = new Godot.Collections.Array<StringName>(); if (context == null || context.Get("unit_state").AsGodotObject() == null) return r; var seen = new Godot.Collections.Dictionary(); var us = context.Get("unit_state").AsGodotObject() as BattleUnitState; var srcIds = preferredSkillIds != null && preferredSkillIds.Count > 0 ? preferredSkillIds : us.known_active_skill_ids; foreach (var rsi in srcIds) { var sid = new StringName(rsi.ToString()); if (sid == "" || seen.ContainsKey(sid)) continue; seen[sid] = true; if (us.known_active_skill_ids.Contains(sid)) r.Add(sid); } return r; }

    protected static SkillDef _get_skill_def(GodotObject context, StringName skillId) => context != null && skillId != "" && context.Get("skill_defs").AsGodotDictionary().ContainsKey(skillId) ? context.Get("skill_defs").AsGodotDictionary()[skillId].AsGodotObject() as SkillDef : null;

    protected string _get_skill_cast_block_reason(GodotObject context, SkillDef skillDef) { if (context == null || context.Get("unit_state").AsGodotObject() == null || skillDef?.combat_profile == null) return "技能或目标无效。"; var us = context.Get("unit_state").AsGodotObject() as BattleUnitState; var cp = skillDef.combat_profile as CombatSkillDef; var costs = cp.get_effective_resource_costs(_get_skill_level(us, skillDef.skill_id)); int cd = us.cooldowns.ContainsKey(skillDef.skill_id) ? us.cooldowns[skillDef.skill_id].AsInt32() : 0; if (cd > 0) return $"{skillDef.display_name} 仍在冷却中（{cd}）。"; var lrbr = _get_locked_combat_resource_block_reason(us, costs); if (lrbr.Length > 0) return lrbr; if (us.current_ap < (costs.ContainsKey("ap_cost") ? costs["ap_cost"].AsInt32() : cp.ap_cost)) return "AP不足，无法施放该技能。"; if (us.current_mp < (costs.ContainsKey("mp_cost") ? costs["mp_cost"].AsInt32() : cp.mp_cost)) return "法力不足，无法施放该技能。"; if (us.current_stamina < (costs.ContainsKey("stamina_cost") ? costs["stamina_cost"].AsInt32() : cp.stamina_cost)) return "体力不足，无法施放该技能。"; if (us.current_aura < (costs.ContainsKey("aura_cost") ? costs["aura_cost"].AsInt32() : cp.aura_cost)) return "斗气不足，无法施放该技能。"; return ""; }

    protected static string _get_locked_combat_resource_block_reason(BattleUnitState us, Godot.Collections.Dictionary costs) { if (us == null) return "技能施放者无效。"; if ((costs.ContainsKey("mp_cost") ? costs["mp_cost"].AsInt32() : 0) > 0 && !us.has_combat_resource_unlocked(BattleUnitState.COMBAT_RESOURCE_MP())) return "法力尚未解锁，无法施放该技能。"; if ((costs.ContainsKey("stamina_cost") ? costs["stamina_cost"].AsInt32() : 0) > 0 && !us.has_combat_resource_unlocked(BattleUnitState.COMBAT_RESOURCE_STAMINA())) return "体力尚未解锁，无法施放该技能。"; if ((costs.ContainsKey("aura_cost") ? costs["aura_cost"].AsInt32() : 0) > 0 && !us.has_combat_resource_unlocked(BattleUnitState.COMBAT_RESOURCE_AURA())) return "斗气尚未解锁，无法施放该技能。"; return ""; }

