    protected static bool _is_better_skill_score_input(GodotObject candidate, GodotObject best) { if (candidate == null) return false; if (best == null) return true; if (candidate.Call("estimated_friendly_lethal_target_count").AsInt32() != best.Call("estimated_friendly_lethal_target_count").AsInt32()) return candidate.Call("estimated_friendly_lethal_target_count").AsInt32() < best.Call("estimated_friendly_lethal_target_count").AsInt32(); if (candidate.Call("estimated_friendly_fire_target_count").AsInt32() != best.Call("estimated_friendly_fire_target_count").AsInt32()) return candidate.Call("estimated_friendly_fire_target_count").AsInt32() < best.Call("estimated_friendly_fire_target_count").AsInt32(); if (candidate.Call("friendly_fire_penalty_score").AsInt32() != best.Call("friendly_fire_penalty_score").AsInt32()) return candidate.Call("friendly_fire_penalty_score").AsInt32() < best.Call("friendly_fire_penalty_score").AsInt32(); int src = _compare_post_action_survival_risk(candidate, best); if (src != 0) return src > 0; if (candidate.Call("estimated_lethal_threat_target_count").AsInt32() != best.Call("estimated_lethal_threat_target_count").AsInt32()) return candidate.Call("estimated_lethal_threat_target_count").AsInt32() > best.Call("estimated_lethal_threat_target_count").AsInt32(); if (candidate.Call("estimated_lethal_target_count").AsInt32() != best.Call("estimated_lethal_target_count").AsInt32()) return candidate.Call("estimated_lethal_target_count").AsInt32() > best.Call("estimated_lethal_target_count").AsInt32(); bool ci = _is_emergency_survival_score_input(candidate), bi = _is_emergency_survival_score_input(best); if (ci != bi) return ci; if (candidate.Call("estimated_lethal_target_count").AsInt32() > 0 && best.Call("estimated_lethal_target_count").AsInt32() > 0) { if (candidate.Call("total_score").AsInt32() != best.Call("total_score").AsInt32()) return candidate.Call("total_score").AsInt32() > best.Call("total_score").AsInt32(); if (candidate.Call("hit_payoff_score").AsInt32() != best.Call("hit_payoff_score").AsInt32()) return candidate.Call("hit_payoff_score").AsInt32() > best.Call("hit_payoff_score").AsInt32(); if (candidate.Call("effective_target_count").AsInt32() != best.Call("effective_target_count").AsInt32()) return candidate.Call("effective_target_count").AsInt32() > best.Call("effective_target_count").AsInt32(); int lnr = _compare_nonfatal_post_action_survival_risk(candidate, best); if (lnr != 0) return lnr > 0; if (candidate.Call("resource_cost_score").AsInt32() != best.Call("resource_cost_score").AsInt32()) return candidate.Call("resource_cost_score").AsInt32() < best.Call("resource_cost_score").AsInt32(); } if (candidate.Call("score_bucket_priority").AsInt32() != best.Call("score_bucket_priority").AsInt32()) return candidate.Call("score_bucket_priority").AsInt32() > best.Call("score_bucket_priority").AsInt32(); if (candidate.Call("total_score").AsInt32() != best.Call("total_score").AsInt32()) return candidate.Call("total_score").AsInt32() > best.Call("total_score").AsInt32(); if (candidate.Call("hit_payoff_score").AsInt32() != best.Call("hit_payoff_score").AsInt32()) return candidate.Call("hit_payoff_score").AsInt32() > best.Call("hit_payoff_score").AsInt32(); if (candidate.Call("effective_target_count").AsInt32() != best.Call("effective_target_count").AsInt32()) return candidate.Call("effective_target_count").AsInt32() > best.Call("effective_target_count").AsInt32(); if (candidate.Call("target_count").AsInt32() != best.Call("target_count").AsInt32()) return candidate.Call("target_count").AsInt32() > best.Call("target_count").AsInt32(); int nr = _compare_nonfatal_post_action_survival_risk(candidate, best); if (nr != 0) return nr > 0; if (candidate.Call("position_objective_score").AsInt32() != best.Call("position_objective_score").AsInt32()) return candidate.Call("position_objective_score").AsInt32() > best.Call("position_objective_score").AsInt32(); return candidate.Call("resource_cost_score").AsInt32() < best.Call("resource_cost_score").AsInt32(); }

    private static bool _is_emergency_survival_score_input(GodotObject si) { if (si == null) return false; if (si.Call("score_bucket_id").AsStringName() != "archer_survival") return false; if (si.Call("has_post_action_threat_projection").AsBool()) { if (si.Call("pre_action_is_lethal_survival_risk").AsBool() && !si.Call("post_action_is_lethal_survival_risk").AsBool()) return true; if (si.Call("pre_action_threat_expected_damage").AsInt32() > si.Call("post_action_remaining_threat_expected_damage").AsInt32() && si.Call("post_action_survival_margin").AsInt32() >= 0) return true; } if (si.Call("target_count").AsInt32() > 0 || si.Call("effective_target_count").AsInt32() > 0) return false; if (si.Call("enemy_target_count").AsInt32() > 0 || si.Call("ally_target_count").AsInt32() > 0) return false; if (si.Call("estimated_damage").AsInt32() != 0 || si.Call("estimated_control_count").AsInt32() != 0) return false; if (si.Call("position_current_distance").AsInt32() >= 0 && si.Call("position_safe_distance").AsInt32() > 0) { int cg = si.Call("position_safe_distance").AsInt32() - si.Call("position_current_distance").AsInt32(); if (cg < 2) return false; if (si.Call("distance_to_primary_coord").AsInt32() >= 0) return si.Call("distance_to_primary_coord").AsInt32() >= si.Call("position_safe_distance").AsInt32(); return si.Call("position_objective_score").AsInt32() > 0; } return si.Call("position_objective_score").AsInt32() > 0; }

    private static int _compare_post_action_survival_risk(GodotObject c, GodotObject b) { if (c == null || b == null) return 0; if (!c.Call("has_post_action_threat_projection").AsBool() || !b.Call("has_post_action_threat_projection").AsBool()) return 0; bool cf = c.Call("post_action_is_lethal_survival_risk").AsBool(), bf = b.Call("post_action_is_lethal_survival_risk").AsBool(); if (cf != bf) return cf ? -1 : 1; return 0; }

    private static int _compare_nonfatal_post_action_survival_risk(GodotObject c, GodotObject b) { if (c == null || b == null) return 0; if (!c.Call("has_post_action_threat_projection").AsBool() || !b.Call("has_post_action_threat_projection").AsBool()) return 0; if (c.Call("post_action_is_lethal_survival_risk").AsBool() || b.Call("post_action_is_lethal_survival_risk").AsBool()) return 0; bool ctf = c.Call("post_action_remaining_threat_count").AsInt32() <= 0, btf = b.Call("post_action_remaining_threat_count").AsInt32() <= 0; if (ctf != btf) return ctf ? 1 : -1; int cd = c.Call("post_action_remaining_threat_expected_damage").AsInt32(), bd = b.Call("post_action_remaining_threat_expected_damage").AsInt32(); if (cd != bd) return cd < bd ? 1 : -1; int cc = c.Call("post_action_remaining_threat_count").AsInt32(), bc = b.Call("post_action_remaining_threat_count").AsInt32(); if (cc != bc) return cc < bc ? 1 : -1; int cm = c.Call("post_action_survival_margin").AsInt32(), bm = b.Call("post_action_survival_margin").AsInt32(); if (cm != bm) return cm > bm ? 1 : -1; return 0; }

    protected static BattleCommand _build_wait_command(GodotObject context) => EnemyAiActionHelper.build_wait_command(context);
    protected static BattleCommand _build_move_command(GodotObject context, Vector2I targetCoord) => EnemyAiActionHelper.build_move_command(context, targetCoord);
    protected static BattleCommand _build_unit_skill_command(GodotObject context, StringName skillId, GodotObject targetUnit, StringName skillVariantId = default) => EnemyAiActionHelper.build_unit_skill_command(context, skillId, targetUnit as BattleUnitState, skillVariantId);

    protected Godot.Collections.Array _collect_unit_skill_effect_defs(SkillDef skillDef, CombatCastVariantDef castVariant, BattleUnitState activeUnit = null) => _skill_resolution_rules.collect_unit_skill_effect_defs(skillDef, castVariant, activeUnit);
