    protected Godot.Collections.Array _collect_units_by_filter(GodotObject context, StringName targetFilter) { var r = new Godot.Collections.Array(); if (context == null || context.Get("state").AsGodotObject() == null || context.Get("unit_state").AsGodotObject() == null) return r; var state = context.Get("state").AsGodotObject() as BattleState; foreach (var uik in state.units.Keys) { var us = state.units[uik].AsGodotObject() as BattleUnitState; if (us != null && us.is_alive && _matches_target_filter(context, us, targetFilter)) r.Add(us); } return r; }

    protected static bool _matches_target_filter(GodotObject context, BattleUnitState us, StringName targetFilter) { if (context == null || context.Get("unit_state").AsGodotObject() == null || us == null) return false; var cu = context.Get("unit_state").AsGodotObject() as BattleUnitState; bool madness = cu.ai_blackboard.ContainsKey("madness_target_any_team") && cu.ai_blackboard["madness_target_any_team"].AsBool(); return BattleTargetTeamRules.is_unit_valid_for_filter(cu, us, targetFilter, new Godot.Collections.Dictionary { {"madness_target_any_team", madness}, {"madness_target_filters", new Godot.Collections.Array { "ally", "enemy", "any" } } }); }

    protected Godot.Collections.Array _sort_target_units(GodotObject context, StringName targetFilter, StringName selector) { if (!_is_supported_target_selector(selector)) return new Godot.Collections.Array(); var ef = targetFilter; if (context != null && context.Get("unit_state").AsGodotObject() != null) { var cu = context.Get("unit_state").AsGodotObject() as BattleUnitState; if (cu.ai_blackboard.ContainsKey("madness_target_any_team") && cu.ai_blackboard["madness_target_any_team"].AsBool() && selector != "self") ef = "any"; else if (selector == "nearest_enemy" || selector == "lowest_hp_enemy" || selector == TARGET_SELECTOR_NEAREST_ROLE_THREAT_ENEMY) ef = "enemy"; else if (selector == "nearest_ally" || selector == "lowest_hp_ally") ef = "ally"; else if (selector == "self") ef = "self"; } var units = _collect_units_by_filter(context, ef); var ft = _resolve_forced_target_unit(context, ef); if (ft != null) return new Godot.Collections.Array { ft }; if (selector == "self") return units; int nd = _resolve_nearest_distance(context, units); var list = new System.Collections.Generic.List<GodotObject>(); foreach (var uv in units) { var us = uv.AsGodotObject() as BattleUnitState; if (us != null) list.Add(us); } list.Sort((l, r) => { var lu = l as BattleUnitState; var ru = r as BattleUnitState; int lhp = _get_hp_basis_points(lu), rhp = _get_hp_basis_points(ru); int ld = _distance_between_units(context, context.Get("unit_state").AsGodotObject() as BattleUnitState, lu), rd = _distance_between_units(context, context.Get("unit_state").AsGodotObject() as BattleUnitState, ru); if (selector == TARGET_SELECTOR_NEAREST_ROLE_THREAT_ENEMY) { int ls = _get_role_threat_selector_score(context, lu, nd, ld), rs = _get_role_threat_selector_score(context, ru, nd, rd); if (ls != rs) return rs.CompareTo(ls); } if (selector == "lowest_hp_enemy" || selector == "lowest_hp_ally") { if (lhp != rhp) return lhp.CompareTo(rhp); if (ld != rd) return ld.CompareTo(rd); return ((string)lu.unit_id).CompareTo((string)ru.unit_id); } if (ld == rd) { if (lhp != rhp) return lhp.CompareTo(rhp); return ((string)lu.unit_id).CompareTo((string)ru.unit_id); } return ld.CompareTo(rd); }); var result = new Godot.Collections.Array(); foreach (var u in list) result.Add(u); return result; }

    protected int _resolve_nearest_distance(GodotObject context, Godot.Collections.Array units) { int nd = 999999; var cu = context.Get("unit_state").AsGodotObject() as BattleUnitState; foreach (var uv in units) { var us = uv.AsGodotObject() as BattleUnitState; if (us != null) nd = Mathf.Min(nd, _distance_between_units(context, cu, us)); } return nd; }

    protected int _get_role_threat_selector_score(GodotObject context, BattleUnitState us, int nearestDist, int dist) { if (us == null) return 0; int tr = _resolve_unit_effective_threat_range(context, us); bool lrt = tr >= ROLE_THREAT_MIN_EFFECTIVE_RANGE && dist <= nearestDist + ROLE_THREAT_DISTANCE_WINDOW && dist <= ROLE_THREAT_MAX_APPROACH_DISTANCE; if (lrt) return 1000 + tr * 10; if (_resolve_unit_contact_threat_range(context, us) > 0) return 500; return 0; }

    protected int _resolve_unit_contact_threat_range(GodotObject context, BattleUnitState tu) { if (context == null || tu == null) return -1; int br = -1; foreach (var rsi in tu.known_active_skill_ids) { var sid = ProgressionDataUtils.to_string_name(rsi); if (sid == "") continue; var sd = context.Get("skill_defs").AsGodotDictionary().ContainsKey(sid) ? context.Get("skill_defs").AsGodotDictionary()[sid].AsGodotObject() as SkillDef : null; if (!_is_hostile_threat_skill(sd)) continue; if (!_skill_has_tag(sd, "melee") && !_skill_has_tag(sd, "weapon")) continue; int er = BattleRangeService.get_effective_skill_range(tu, sd); if (er <= 0 && _skill_has_tag(sd, "melee")) er = 1; if (er > ROLE_THREAT_MAX_CONTACT_RANGE) continue; br = Mathf.Max(br, er); } int wr = BattleRangeService.get_weapon_attack_range(tu); if (wr > 0 && wr <= ROLE_THREAT_MAX_CONTACT_RANGE) br = Mathf.Max(br, wr); return br; }

    protected static GodotObject _resolve_forced_target_unit(GodotObject context, StringName targetFilter) => context != null && context.HasMethod("resolve_forced_target_unit") ? context.Call("resolve_forced_target_unit", targetFilter).AsGodotObject() : null;

    protected static int _get_hp_basis_points(BattleUnitState us) { if (us?.attribute_snapshot == null) return HP_BASIS_POINTS_DENOMINATOR; int hpm = Mathf.Max(us.attribute_snapshot.Call("get_value", new StringName("hp_max")).AsInt32(), 1); int chp = Mathf.Clamp(us.current_hp, 0, hpm); return Mathf.Clamp(chp * HP_BASIS_POINTS_DENOMINATOR / hpm, 0, HP_BASIS_POINTS_DENOMINATOR); }

    protected static int _distance_between_units(GodotObject context, BattleUnitState a, BattleUnitState b) => context?.Get("grid_service").AsGodotObject() != null ? context.Get("grid_service").AsGodotObject().Call("get_distance_between_units", a, b).AsInt32() : 999999;

    protected static int _distance_from_anchor_to_unit(GodotObject context, BattleUnitState us, Vector2I anchor, BattleUnitState tu) { if (context?.Get("grid_service").AsGodotObject() == null || us == null || tu == null) return 999999; var gs = context.Get("grid_service").AsGodotObject(); us.refresh_footprint(); tu.refresh_footprint(); int bd = 999999; foreach (var sc in gs.Call("get_footprint_coords", anchor, us.footprint_size).AsGodotArray<Vector2I>()) foreach (var tc in tu.occupied_coords) bd = Mathf.Min(bd, gs.Call("get_distance", sc, tc).AsInt32()); return bd; }

    protected static int _get_skill_level(BattleUnitState us, StringName sid) { if (us == null || sid == "") return 0; if (us.known_skill_level_map.ContainsKey(sid)) return us.known_skill_level_map[sid].AsInt32(); return us.known_active_skill_ids.Contains(sid) ? 1 : 0; }

    protected Godot.Collections.Dictionary _resolve_desired_distance_contract(GodotObject context, SkillDef skillDef = null, Godot.Collections.Array<StringName> rangeSkillIds = null) { rangeSkillIds ??= new Godot.Collections.Array<StringName>(); int cm = Get("desired_min_distance").AsInt32(); int cx = Get("desired_max_distance").AsInt32(); int ear = _resolve_effective_attack_range(context, skillDef, rangeSkillIds); int rx = cx; if (ear >= 0) rx = ear; int rm = cm; if (rx >= 0 && rm > rx) rm = rx; return new Godot.Collections.Dictionary { {"desired_min_distance",rm},{"desired_max_distance",Mathf.Max(rx,rm)},{"configured_desired_min_distance",cm},{"configured_desired_max_distance",cx},{"effective_attack_range",ear} }; }

    protected int _resolve_effective_attack_range(GodotObject context, SkillDef skillDef = null, Godot.Collections.Array<StringName> rangeSkillIds = null) { rangeSkillIds ??= new Godot.Collections.Array<StringName>(); if (context?.Get("unit_state").AsGodotObject() == null) return -1; var us = context.Get("unit_state").AsGodotObject() as BattleUnitState; if (skillDef != null) return BattleRangeService.get_effective_skill_threat_range(us, skillDef); int br = -1; foreach (var sid in _resolve_known_skill_ids(context, rangeSkillIds)) { var csd = _get_skill_def(context, sid); if (csd?.combat_profile == null) continue; if (_get_skill_cast_block_reason(context, csd).Length > 0) continue; br = Mathf.Max(br, BattleRangeService.get_effective_skill_threat_range(us, csd)); } return br; }

    protected int _resolve_target_safe_distance(GodotObject context, BattleUnitState tu, int cmsd, int sdm = 1) { int rm = Mathf.Max(cmsd, 0); int tr = _resolve_unit_effective_threat_range(context, tu); return tr <= 0 ? rm : Mathf.Max(rm, tr + Mathf.Max(sdm, 0)); }

    protected int _resolve_unit_effective_threat_range(GodotObject context, BattleUnitState tu) { if (context == null || tu == null) return -1; int br = -1; foreach (var rsi in tu.known_active_skill_ids) { var sid = ProgressionDataUtils.to_string_name(rsi); if (sid == "") continue; var sd = context.Get("skill_defs").AsGodotDictionary().ContainsKey(sid) ? context.Get("skill_defs").AsGodotDictionary()[sid].AsGodotObject() as SkillDef : null; if (!_is_hostile_threat_skill(sd)) continue; br = Mathf.Max(br, BattleRangeService.get_effective_skill_threat_range(tu, sd)); } if (br < 0) br = BattleRangeService.get_weapon_attack_range(tu); return br; }

    protected BattleUnitState _select_most_unsafe_target(GodotObject context, Godot.Collections.Array targets, Vector2I anchorCoord, int cmsd, int sdm = 1) { BattleUnitState bt = null; int bg = -1, bd = 999999; var cu = context.Get("unit_state").AsGodotObject() as BattleUnitState; foreach (var tv in targets) { var tu = tv.AsGodotObject() as BattleUnitState; if (tu == null) continue; int dist = _distance_from_anchor_to_unit(context, cu, anchorCoord, tu); int sd = _resolve_target_safe_distance(context, tu, cmsd, sdm); int ug = Mathf.Max(sd - dist, 0); if (bt == null || ug > bg || (ug == bg && dist < bd)) { bt = tu; bg = ug; bd = dist; } } return bt; }

    protected static bool _is_hostile_threat_skill(SkillDef sd) { if (sd?.combat_profile == null) return false; var cp = sd.combat_profile as CombatSkillDef; var tf = ProgressionDataUtils.to_string_name(cp.target_team_filter); if (tf == "ally" || tf == "self") return false; if (_skill_has_tag(sd, "output") || _skill_has_tag(sd, "melee") || _skill_has_tag(sd, "bow") || _skill_has_tag(sd, "weapon")) return true; if (_effect_list_has_hostile_threat(cp.effect_defs)) return true; foreach (var cv in cp.cast_variants) { if (cv != null && _effect_list_has_hostile_threat(cv.effect_defs)) return true; } return false; }

    protected static bool _skill_has_tag(SkillDef sd, StringName et) { if (sd == null || et == "") return false; foreach (var t in sd.tags) if (ProgressionDataUtils.to_string_name(t) == et) return true; return false; }

    protected static bool _effect_list_has_hostile_threat(Godot.Collections.Array<CombatEffectDef> eds) { foreach (var ed in eds) { if (ed == null) continue; var et = ProgressionDataUtils.to_string_name(ed.effect_type); if (et == "damage" || et == "chain_damage" || et == "charge" || et == "forced_move" || et == "path_step_aoe" || et == "status") return true; } return false; }

    protected Godot.Collections.Array _get_ground_variants(GodotObject context, SkillDef sd) { var v = new Godot.Collections.Array(); if (sd?.combat_profile == null || (sd.combat_profile as CombatSkillDef).target_mode != "ground") return v; var cp = sd.combat_profile as CombatSkillDef; if (cp.cast_variants.Count == 0) { v.Add(_build_implicit_ground_variant(sd)); return v; } int sl = _get_skill_level(context?.Get("unit_state").AsGodotObject() as BattleUnitState, sd.skill_id); foreach (var cv in cp.get_unlocked_cast_variants(sl)) { if (cv != null) v.Add(cv); } return v; }

    protected CombatCastVariantDef _build_implicit_ground_variant(SkillDef sd) { var cv = new CombatCastVariantDef { variant_id = "", display_name = "", target_mode = "ground", footprint_pattern = "single", required_coord_count = 1, effect_defs = new Godot.Collections.Array<Resource>(sd.combat_profile.Get("effect_defs").AsGodotArray()) }; return cv; }

    protected static bool _is_charge_variant(CombatCastVariantDef cv) { if (cv == null) return false; foreach (var ed in cv.effect_defs) { if (ed != null && ed.effect_type == "charge") return true; } return false; }

    protected Godot.Collections.Array _enumerate_ground_target_coord_sets(GodotObject context, CombatCastVariantDef cv) { var r = new Godot.Collections.Array(); if (context?.Get("state").AsGodotObject() == null || context?.Get("grid_service").AsGodotObject() == null || cv == null) return r; var state = context.Get("state").AsGodotObject() as BattleState; var gs = context.Get("grid_service").AsGodotObject(); var seen = new Godot.Collections.Dictionary(); if (cv.footprint_pattern == "line2") { for (int y = 0; y < state.map_size.Y; y++) for (int x = 0; x < state.map_size.X; x++) { var f = new Vector2I(x, y); foreach (var d in new[] { Vector2I.Right, Vector2I.Down }) { var s = f + d; if (!gs.Call("is_inside", state, s).AsBool()) continue; var pair = _sort_coords(new Godot.Collections.Array<Vector2I> { f, s }); var k = _coord_set_key(pair); if (seen.ContainsKey(k)) continue; seen[k] = true; r.Add(pair); } } } else if (cv.footprint_pattern == "square2") { for (int y = 0; y < Mathf.Max(state.map_size.Y - 1, 0); y++) for (int x = 0; x < Mathf.Max(state.map_size.X - 1, 0); x++) { var coords = _sort_coords(new Godot.Collections.Array<Vector2I> { new(x, y), new(x + 1, y), new(x, y + 1), new(x + 1, y + 1) }); var k = _coord_set_key(coords); if (seen.ContainsKey(k)) continue; seen[k] = true; r.Add(coords); } } else { for (int y = 0; y < state.map_size.Y; y++) for (int x = 0; x < state.map_size.X; x++) r.Add(new Godot.Collections.Array<Vector2I> { new(x, y) }); } return r; }

    protected static Godot.Collections.Array<Vector2I> _sort_coords(Godot.Collections.Array<Vector2I> coords) => EnemyAiActionHelper.sort_coords(coords);
    protected static string _coord_set_key(Godot.Collections.Array<Vector2I> coords) => EnemyAiActionHelper.coord_set_key(coords);

    protected Godot.Collections.Dictionary _begin_action_trace(GodotObject context, Godot.Collections.Dictionary metadata = null) { var tm = _merge_runtime_action_metadata(context, metadata ?? new Godot.Collections.Dictionary()); var rsb = ProgressionDataUtils.to_string_name(tm.ContainsKey("score_bucket_id") ? tm["score_bucket_id"] : score_bucket_id); return EnemyAiActionHelper.begin_action_trace(action_id, rsb, context, tm); }

    protected Godot.Collections.Dictionary _merge_runtime_action_metadata(GodotObject context, Godot.Collections.Dictionary metadata) { if (context != null && context.HasMethod("merge_current_action_metadata")) return context.Call("merge_current_action_metadata", metadata).AsGodotDictionary(); return metadata.Duplicate(true); }

    protected static void _trace_count_increment(Godot.Collections.Dictionary actionTrace, string key, int amount = 1) => EnemyAiActionHelper.trace_count_increment(actionTrace, key, amount);
    protected static void _trace_add_block_reason(Godot.Collections.Dictionary actionTrace, string reasonKey) => EnemyAiActionHelper.trace_add_block_reason(actionTrace, reasonKey);
    protected static void _trace_offer_candidate(Godot.Collections.Dictionary actionTrace, Godot.Collections.Dictionary candidateSummary, int keepCount = 5) => EnemyAiActionHelper.trace_offer_candidate(actionTrace, candidateSummary, keepCount);
    protected static StringName _finalize_action_trace(GodotObject context, Godot.Collections.Dictionary actionTrace, BattleAiDecision bestDecision = null) => EnemyAiActionHelper.finalize_action_trace(context, actionTrace, bestDecision);
    protected static Godot.Collections.Dictionary _build_candidate_summary(string label, BattleCommand command, GodotObject scoreInput = null, Godot.Collections.Dictionary extra = null) => EnemyAiActionHelper.build_candidate_summary(label, command, scoreInput, extra ?? new Godot.Collections.Dictionary());
    protected static string _format_skill_variant_label(SkillDef sd, CombatCastVariantDef cv) => EnemyAiActionHelper.format_skill_variant_label(sd, cv);
    protected static Godot.Collections.Dictionary _build_command_summary(BattleCommand command) => EnemyAiActionHelper.build_command_summary(command);
}
